def build_and_evaluate(operands, operators):
    """
    Builds a string from the given operands and operators,
    then evaluates the expression safely using eval().
    """
    if not operands:
        return None

    if len(operands) == 1:
        return operands[0]

    if len(operands) != len(operators) + 1:
        raise ValueError("Number of operands must be exactly one more than number of operators")

    # Build the expression string
    parts = []
    for i, op in enumerate(operators):
        parts.append(str(operands[i]))
        parts.append(op)
    parts.append(str(operands[-1]))

    expression = "".join(parts)

    # Evaluate the expression
    try:
        return eval(expression)
    except Exception as e:
        raise ValueError(f"Failed to evaluate expression '{expression}': {e}")

